actions.action:
// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate UT state additions
            double additions = 0.0;

            // UT requires addback of:
            // - Federal interest income (taxable to UT)
            // - State income tax refunds (if included in federal income)
            // - Certain expenses related to exempt income
            // - IRC 199A deduction if state does not conform

            // Example additions (would be calculated from entity fields):
            // additions += revenue.federal_bond_interest;
            // additions += result.state_tax_refund;
            // additions += result.section_199a_deduction;

            apportionment.state_additions = additions;

            // Calculate UT state subtractions
            double subtractions = 0.0;

            // UT allows subtraction of:
            // - UT municipal bond interest (exempt for UT purposes)
            // - State income taxes paid (not deductible for state purposes)
            // - UT net operating loss deduction (if applicable)
            // - Certain dividend income adjustments

            // Example subtractions (would be calculated from entity fields):
            // subtractions += revenue.ut_municipal_interest;
            // subtractions += result.state_taxes_paid;
            // subtractions += result.ut_nol_deduction;

            apportionment.state_subtractions = subtractions;

            // UT uses 4.50% flat rate (reduced from 4.55% in 2025)
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract UT state credits
            // UT offers various credits: renewable energy, research activities,
            // economic development, historic preservation, etc.
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
